import{c as t,Z as o,Q as r,j as i,m as l,o as s}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"春望","description":"","frontmatter":{"title":"春望","author":"杜甫","dynasty":"唐"},"headers":[],"relativePath":"books/shici/tangshi/6.md","filePath":"books/shici/tangshi/6.md"}'),n={name:"books/shici/tangshi/6.md"};function h(c,a,d,u,p,_){const e=o("PoemNav");return r(),i("div",null,[a[0]||(a[0]=l('<h1 id="春望" tabindex="-1">春望 <a class="header-anchor" href="#春望" aria-label="Permalink to &quot;春望&quot;">​</a></h1><p><strong>[唐] <a href="/authors/dufu.html">杜甫</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>国破山河在，城春草木深。 感时花溅泪，恨别鸟惊心。 烽火连三月，家书抵万金。 白头搔更短，浑欲不胜簪。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>国破：指国都长安被叛军占领</li><li>感时：为时事而感伤</li><li>烽火：古时边防报警的烟火，这里指战争</li><li>抵：值，相当</li><li>浑欲：简直要</li><li>不胜簪：插不上簪子</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>国都沦陷，只有山河依旧；春天来临，城中荒草丛生，林木苍苍。感伤时事，看到花开反而落泪；怨恨离别，听到鸟鸣反而心惊。战火连绵不断，已经持续了三个月；一封家书珍贵得值上万两黄金。愁绪缠绕，白发越搔越稀疏，简直要插不上簪子了。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗写于安史之乱期间，诗人目睹长安城一片萧条零落的景象，百感交集。前四句写春日长安凄惨破败的景象，饱含着兴衰感慨；后四句写诗人挂念亲人、心系国事的情怀，充溢着凄苦哀思。全诗格律严整，颔联分别以&quot;感时花溅泪&quot;应首联国破之叹，以&quot;恨别鸟惊心&quot;应颈联思家之忧，表现了诗人忧国忧民、感时伤怀的高尚情感。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>杜甫</strong>（712年－770年），字子美，自号少陵野老，唐代伟大的现实主义诗人，被后人称为“诗圣”，其诗被称为“诗史”。与李白并称“李杜”。</p><p><a href="/authors/dufu.html">查看作者详情 →</a></p></blockquote>',13)),s(e)])}const q=t(n,[["render",h]]);export{f as __pageData,q as default};
